            <img src={IMG_GROUP_LOGO} alt="LMK Group" style={{ width: 68, height: 68, borderRadius: 14, objectFit: "contain", background: "#fff", border: "1px solid #f0f0f0", marginBottom: 10, display: "block" }} />
